window.kbPageData["views/entry/k-d226eb6a08404fcd"] = {"key":"entry/k-d226eb6a08404fcd","state":{"route":"entry/k-d226eb6a08404fcd"},"node":{"id":"k-d226eb6a08404fcd","mode":"k","title":"必要条件的蕴含方向","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2024 C类 行测#91"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"如果甲成立必须以乙成立为前提，乙就是甲的必要条件。甲成立可推出乙成立，乙不成立可推出甲不成立。","review":{"definition":"如果甲成立必须以乙成立为前提，乙就是甲的必要条件。甲成立可推出乙成立，乙不成立可推出甲不成立。","explanation":"第91题中，“除非……否则不能……”表示鸟能飞向天空就必须同时满足两翼健壮、以共同的力量推动身体，故②成立。①把两个必要条件当成了充分条件，④从不能飞反推至少一个条件不成立，二者均无法由题干推出。","references":[],"evidence":"除非两翼健壮并以共同的力量来推动身体，否则它不能飞向天空","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#91":{"paper":"江苏 2024 C类 行测","n":91,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",19],"asrc":["02d6b49839583bdaf297.pdf",27],"card":"79fa5756e135d438d56147d7","links":[{"id":"k-d226eb6a08404fcd","role":"直接考查","why":"能飞推出必须满足两个条件，满足两个条件只确立了飞行的必要条件。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d226eb6a08404fcd":[["江苏 2024 C类 行测#91"]]}};
